	},
})

Translate("ruRU", "cathedral-square", {
	title = "Соборная площадь",
	sections = {
		{
			title = "Обзор",
			text = [=[Соборная площадь — большая открытая площадь в сердце {link:stormwind-city}Штормград{/link}а. На ее северном конце возвышается {link:cathedral-of-light}Собор Света{/link}, самый большой дом {link:holy-light}Свет{/link}а на юге. Вокруг площади стоят Ратуша, где держит свою контору зодчий {link:baros-alexston}Барос Алекстон{/link}, и залы, где обучаются духовенство и паладины города. На каменных плитах упражняются солдаты. Паломники приходят молиться. Эта площадь — место, где Штормград показывает себя таким, каким хочет казаться: верным, упорядоченным и сильным.]=],
		},
	},
})

Translate("ruRU", "old-town", {
