		{
			title = "Обзор",
			text = [=[Квартал Дворфов стоит на севере {link:stormwind-city}Штормград{/link}а, у городских стен. {link:dwarves}Дворфы{/link} {link:ironforge}Стальгорна{/link}, живущие в Штормграде, держат этот квартал как свой собственный. Здесь самые шумные кузницы города, зал {link:explorers-league}Лиги исследователей{/link} и вход в {red:deeprun-tram}Подземный поезд{/red}, который идет под горами в Стальгорн. Этот квартал — знак старой дружбы двух королевств. Его кузнецы говорят, и отнюдь не шепотом, что лучшую сталь в Штормграде делают на их улице.]=],
		},
	},
})

Translate("ruRU", "mage-quarter", {
	title = "Квартал Магов",
	sections = {
		{
			title = "Обзор",
			text = [=[Квартал Магов лежит на юго-западе {link:stormwind-city}Штормград{/link}а, где над каналами поднимаются лиловые крыши. В его сердце стоит Святилище Мага, и там маги города обучают своих учеников {link:arcane-magic}тайной магии{/link}. Не всякая магия здесь законна. Под таверной «Забитый ягненок» чернокнижники сходятся в подвале и изучают силы, которые Церковь осуждает. Близ квартала, у каналов, стоят мрачные ворота {link:the-stockade}Тюрьмы{/link}, где собственные узники оттеснили стражу к самым дверям.]=],
