Translate("ruRU", "the-park", {
	title = "Парк",
	sections = {
		{
			title = "Обзор",
			text = [=[Парк — зеленый квартал на северо-западе {link:stormwind-city}Штормград{/link}а. Между тихими дорожками стоят старые деревья. Это самое спокойное место в многолюдном городе, и лежит оно под самыми стенами Крепости Штормграда. Горожане приходят сюда отдохнуть, пройтись и поговорить. Неподалеку Рой Льюэллс держит книжный клуб. Его участники после закрытия собираются в подвале, чтобы спорить об истории и идеях, с книгами, взятыми в Королевской библиотеке, и с угощением, которым Рой охотно делится с теми, кто ему помогает.]=],
		},
	},
})

Translate("ruRU", "stormwind-keep", {
	title = "Крепость Штормграда",
	aliases = { "Замок Штормграда" },
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Штормграда — твердыня на северном конце города, престол королей дома Риннов. Ее тронный зал охраняют днем и ночью. Там юный {link:anduin-wrynn}король Андуин{/link} сидит рядом с верховным лордом {link:bolvar-fordragon}Болвар{/link}ом Фордрагоном, и при них обоих состоит {link:katrana-prestor}леди Катрана Престор{/link}. В крепости также находятся {link:royal-library}Королевская библиотека{/link}, службы городской стражи и обнесенный стеной сад, где прогуливаются придворные лорды. Не всякий разговор в этом саду предназначен для верных ушей.]=],
		},
	},
})

Translate("ruRU", "stormwind-harbor", {
	title = "Гавань Штормграда",
	aliases = { "гавань Штормграда" },
	sections = {
		{
			title = "Обзор",
			text = [=[В гавани {link:stormwind-city}Штормград{/link}а вновь стало людно. Новое судно теперь ходит через море от ее южного причала в {link:auberdine}Аубердин{/link} на {link:darkshore}Темных берегах{/link} и возит припасы, письма и путников между королевством и землями {link:night-elves}ночных эльфов{/link}. Писцы считают груз по ящикам, а портовых рабочих вечно не хватает. Стражники и канониры следят за водой. Купцы города уже послали за море родню торговать в Аубердине, а обратно приходят письма с просьбами о помощи. Впервые за многие годы город смотрит вовне, за море.]=],
		},
	},
})

Translate("ruRU", "valley-of-heroes", {
	title = "Аллея Героев",
	sections = {
		{
			title = "Обзор",
			text = [=[Аллея Героев — парадный подступ к {link:stormwind-city}Штормград{/link}у. Дорога из {link:elwynn-forest}Элвинн{/link}ского леса пересекает длинный мост и проходит между высокими статуями, прежде чем достичь главных ворот города. Под ними проходит всякий путник, который приходит в Штормград по суше. Городская стража несет здесь бдительный дозор, ибо ворота — первая защита столицы и первое, что видят ее гости. Сюда прибывают гонцы от дальних маршалов королевства, и оруженосцы несут их вести от ворот в тронный зал.]=],
		},
	},
})

Translate("ruRU", "cathedral-of-light", {
	title = "Собор Света",
	aliases = { "Собор Света" },
	sections = {
		{
			title = "Обзор",
			text = [=[Собор Света — величайший дом {link:holy-light}Света{/link} в королевстве {link:stormwind-city}Штормград{/link}. Собор возвышается над Соборной площадью в сердце города. Из его залов архиепископ {link:archbishop-benedictus}Бенедикт{/link} ведет Церковь. Жрецы наставляют там верующих, а в его боковых покоях {link:grayson-shadowbreaker}лорд Грейсон Сокрушитель Теней{/link} обучает паладинов державы.]=],
		},
		{
			title = "Хранитель реликвий",
			text = [=[Собор не только молится. Сюда приносят святыни, чтобы сберечь их, и проклятые вещи, чтобы очистить их. Когда было возвращено проклятое Око Палета, его доставили архиепископу. Когда в Болотине нашли маленькую статуэтку короля {link:terenas-menethil}Теренаса Менетила{/link}, показалось, что вокруг нее собирается {link:holy-light}Свет{/link}, и ее тоже отправили в собор на сохранение. Верующие {link:stormwind-city}Штормград{/link}а полагаются на то, что все, что попадает в собор, будет под надежной охраной.]=],
		},
		{
			title = "Служители собора",
			text = [=[Собор — дом не одного лишь архиепископа. В его залах служат епископы, братья и послушники. Брат Кристоф готовит там свои проповеди по книгам из Королевской библиотеки, а паладины, которых учит лорд {link:captain-grayson}Грейсон{/link}, упражняются в его стенах. Слово Церкви расходится отсюда в {link:northshire-abbey}Аббатство Североземья{/link} и в каждую часовню державы.]=],
		},
	},
})

Translate("ruRU", "royal-library", {
	title = "Королевская библиотека",
	aliases = { "Библиотека Штормграда", "библиотека Штормграда" },
