})

Translate("ruRU", "varian-wrynn", {
	title = "Вариан Ринн",
	subtitle = "Пропавший король Штормграда",
	found = "Нигде; король исчез",
	hint = "Узнайте о короле, которого потерял Штормград.",
	allegiance = "Королевство Штормград · Дом Риннов",
	aliases = { "Вариан", "король Вариан", "король Вариан Ринн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Вариан Ринн — король {link:stormwind-city}Штормград{/link}а, сын короля {link:llane-wrynn}Ллейна Ринна{/link} и отец юного Андуина. Мальчиком он видел, как горит королевство его отца, возмужал в изгнании и вернулся домой править городом, отстроенным из пепла. Теперь его нет. Он отправился в дипломатическую поездку и не вернулся, и ни единой вести о нем не дошло до его двора.]=],
		},
		{
			title = "Значение",
			text = [=[Отсутствие короля определяет всю жизнь {link:stormwind-city}Штормград{/link}а. Его титул носит ребенок. От его имени правит регент. Его войско далеко, его дороги небезопасны, а его знать ссорится в залах крепости. Каждый верный подданный королевства задает один и тот же вопрос, и никто при дворе не может на него ответить: где король? Пока он не вернется, Штормград должны удерживать те, кто стоял у его трона.]=],
		},
		{
			title = "Деяния",
			text = [=[• Мальчиком он пережил падение {link:stormwind-city}Штормград{/link}а в {link:first-war}Первую войну{/link}, когда был убит его отец.
• Сэр {link:anduin-lothar}Андуин Лотар{/link} увез его на север, в {link:lordaeron}Лордерон{/link}, и он вырос в изгнании.
• После {link:second-war}Второй войны{/link} он вернулся, чтобы занять трон отстроенного Штормграда.
• Он взял в жены ту, что стала королевой, — {link:tiffin-wrynn}Тиффин Ринн{/link}, и потерял ее в бунте каменщиков.
• Он отправился с дипломатическим поручением и исчез.]=],
		},
		{
			title = "Чего не сохранили летописи",
			text = [=[Ни одна летопись не называет года, когда исчез король Вариан, и не говорит, где его видели в последний раз. Что с ним сталось, в {link:stormwind-city}Штормград{/link}е не знают.]=],
		},
	},
	chapters = {
		{
			title = "Возвращение изгнанника",
			hint = "Узнайте, как был отстроен Штормград.",
			text = [=[Мальчик, бежавший из горящего города, вернулся домой мужчиной. {link:stormwind-city}Штормград{/link} отстроили каменщики, и Вариан был коронован в залах своего отца. Он взял королеву, {link:tiffin-wrynn}Тиффин{/link}, и она родила ему сына, которого он назвал в честь героя, спасшего ему жизнь. Какое-то время казалось, что дом Риннов прошел сквозь огонь.]=],
		},
		{
			title = "Смерть королевы",
			hint = "Узнайте, чего стоил королю бунт каменщиков.",
			text = [=[Когда {link:house-of-nobles}Палата знати{/link} отказалась платить {link:stonemasons-guild}Гильдии каменщиков{/link}, каменщики поднялись в гневе. В хаосе этого бунта {link:tiffin-wrynn}королева Тиффин{/link} была убита. Каменщиков изгнали из города, а королю пришлось растить сына одному. Из изгнания каменщиков родилось {link:defias-brotherhood}Братство Справедливости{/link}.]=],
		},
		{
			title = "Пустой трон",
			hint = "Доставьте королю донесение о Братстве Справедливости.",
			text = [=[Донесение предназначалось для рук самого короля. В нем говорилось о братстве, которое возглавил {link:edwin-vancleef}ван Клиф{/link}, и об измене, раскрытой при дворе. Но короля не было, и прочесть его он не мог. Вместо него донесение приняла {link:katrana-prestor}леди Престор{/link}, и она сказала лишь, что Вариан отбыл с дипломатическим поручением. Куда он отправился, она не сказала.]=],
		},
	},
	mentions = {
