})

Translate("ruRU", "anduin-wrynn", {
	title = "Андуин Ринн",
	subtitle = "Мальчик-король Штормграда",
	found = "Тронный зал Крепости Штормграда",
	hint = "Добейтесь аудиенции в тронном зале Крепости Штормграда.",
