	aliases = { "король Андуин", "принц Андуин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Андуин Ринн — единственный сын короля {link:varian-wrynn}Вариан{/link}а и королевы {link:tiffin-wrynn}Тиффин{/link}. Он еще ребенок, но, раз его отца нет, носит титул короля {link:stormwind-city}Штормград{/link}а. Он стоит в тронном зале крепости среди взрослых мужей в доспехах и придворных дам, а {link:bolvar-fordragon}верховный лорд Болвар Фордрагон{/link} правит от его имени.]=],
		},
		{
			title = "Значение",
			text = [=[Андуин — будущее дома Риннов и живая надежда его королевства. Пока он стоит в тронном зале, народ {link:stormwind-city}Штормград{/link}а может верить, что род его королей не прервался. Его назвали в честь героя, сэра {link:anduin-lothar}Андуина Лотара{/link}, защитника, который спас его отца, когда тот был мальчиком, и вынес его из горящего города.

Положение мальчика необычно. Он носит высший титул в державе, но решения державы принимают другие. Каждый проситель, входящий в тронный зал, кланяется ему. Мало кто из них с ним заговаривает. Они говорят с регентом рядом с ним и с придворной дамой, что стоит возле них обоих. Андуин все это видит и слышит.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он потерял мать в бунте каменщиков, когда был совсем мал.
• Он носит титул своего отца, пока король пропал.
• Он держит двор рядом с регентом и лордами королевства.
• Он ждет в тронном зале своего отца вестей об отце.]=],
		},
		{
			title = "Чего не сохранили летописи",
			text = [=[Ни одна летопись не называет года, когда родился Андуин, и его точного возраста в эти дни. Записи двора мало говорят о его собственных мыслях.]=],
		},
	},
	chapters = {
		{
			title = "Ребенок на троне",
			hint = "Поговорите с юным королем в Крепости Штормграда.",
			text = [=[Мальчик научился стоять неподвижно во время долгих аудиенций. Он слушает маршалов и знать, прошения с ферм и донесения с границ. Он потерял мать и, быть может, отца. Двор называет его королем. Те, кто смотрит внимательно, видят, что он еще и ребенок, ждущий вестей, которые все не приходят.]=],
		},
		{
			title = "Наследник двух домов",
			hint = "Узнайте историю дома Риннов.",
			text = [=[Его дед, король {link:llane-wrynn}Ллейн Ринн{/link}, погиб при падении старого {link:stormwind-city}Штормград{/link}а. Его отец вырос в изгнании при дворе в {link:lordaeron}Лордерон{/link}е, где правил {link:terenas-menethil}король Теренас{/link}, и вернулся строить новый город. Его мать, {link:tiffin-wrynn}королева Тиффин{/link}, погибла на улицах этого города. Андуин унаследовал и корону, и ее раны.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Вариан Ринн", note = "его отец, пропал" },
		{ id = "tiffin-wrynn", name = "Тиффин Ринн", note = "его мать" },
		{ id = "bolvar-fordragon", name = "Болвар Фордрагон", note = "его регент и защитник" },
		{ id = "katrana-prestor", name = "Катрана Престор", note = "дама его двора" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "герой, в честь которого он назван" },
	},
})

Translate("ruRU", "bolvar-fordragon", {
	title = "Болвар Фордрагон",
	subtitle = "Регент Штормграда",
	found = "Тронный зал Крепости Штормграда",
	hint = "Разыщите верховного лорда, который правит из тронного зала.",
	allegiance = "Королевство Штормград · Свет",
	aliases = { "Болвар", "верховный лорд Болвар Фордрагон", "верховный лорд Фордрагон", "Фордрагон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Верховный лорд Болвар Фордрагон — защитник {link:holy-light}Света{/link} и регент {link:stormwind-city}Штормград{/link}а. Пока {link:varian-wrynn}король Вариан{/link} пропал, а его сын еще ребенок, Болвар правит королевством из тронного зала крепости. Он стоит рядом с юным королем в сияющих доспехах, и каждый приказ, что покидает {link:stormwind-keep}Крепость Штормграда{/link}, уходит под его печатью.]=],
		},
		{
			title = "Значение",
			text = [=[Болвар удерживает державу от распада в самый смутный ее час. Ему приходится отвечать на мольбы с каждой неспокойной границы, от Красногорья до Болотины, с войском, которое и так растянуто до предела. Он опирается на советы тех, кто его окружает. Среди них никого не слушают чаще, чем леди Катрану Престор.]=],
