			title = "Деяния",
			text = [=[• Он правит {link:stormwind-city}Штормград{/link}ом как регент от имени мальчика-короля.
• Он лично охраняет юного короля в тронном зале крепости.
• Он принимает прошения городов и маршалов королевства.
• Он посылает защитников справляться с угрозами, до которых не может дотянуться войско.]=],
		},
	},
	chapters = {
		{
			title = "Мольба Приозерья",
			hint = "Доставьте регенту мольбу мирового судьи Приозерья.",
			text = [=[Мировой судья {link:magistrate-solomon}Соломон{/link} из Приозерья написал регенту об опасностях, которые смыкаются вокруг {link:redridge-mountains}Красногорья{/link}, и умолял корону о помощи. Болвар не пожелал решать один. Сначала он послал гонца поговорить с {link:katrana-prestor}леди Престор{/link} и лишь после ее совета записал свой указ для Приозерья.]=],
		},
		{
			title = "Статуя старого короля",
			hint = "Доставьте регенту реликвию короля Теренаса из Болотины.",
			text = [=[Из Гавани Менетилов в Болотине прибыла маленькая статуэтка короля {link:terenas-menethil}Теренаса Менетила{/link}, возвращенная после долгих поисков. Хранители гавани боялись держать ее в краю, осажденном врагами. Они послали ее прямо регенту, веря, что Болвар будет знать, где следует хранить такую память о короле {link:lordaeron}Лордерон{/link}а.]=],
		},
		{
			title = "Лорд-следопыт",
			hint = "Принесите регенту вести о человеке по имени Натанос Маррис.",
			text = [=[В крепость пришла весть о том, что {link:nathanos-blightcaller}Натанос Маррис{/link}, некогда лорд-следопыт, теперь служит Отрекшимся под именем Натанос Гнилостень. Болвар не счел это мелочью. Он призвал войско выступить в {link:eastern-plaguelands}Восточные Чумные земли{/link} и покончить с этим врагом, и предупредил, что {link:horde}Орда{/link} будет защищать лорда-следопыта ценой жизни.]=],
		},
		{
			title = "Большой маскарад",
			hint = [=[Встаньте рядом с верховным лордом, когда правда откроется в его собственном тронном зале.]=],
			text = [=[Маршал {red:reginald-windsor}Реджинальд Виндзор{/red} пришел в тронный зал с доказательствами заговора в самом сердце двора. Когда он заговорил, женщина, так долго дававшая регенту советы, явила свой истинный облик. То была {link:onyxia}Ониксия{/link}, дочь {link:deathwing}Смертокрыла{/link}. Болвар был ее марионеткой, и она сказала ему это в лицо. {link:wynd-nightchaser}Винд{/link}зор пал, а дракон бежал. После нее остались потрясенный регент и двор, который больше не мог доверять своим.]=],
		},
	},
	mentions = {
		{ text = "Истинные хозяева" },
		{ text = "Истинные хозяева" },
		{ text = "Друг семьи" },
		{ text = "Первый и последний" },
		{ text = "Грядет {link:nathanos-blightcaller}Гнилостень{/link}" },
		{ text = "Порядок должен быть восстановлен" },
		{ text = "Большой маскарад" },
		{ text = "Око дракона" },
	},
	bonds = {
		{ id = "anduin-wrynn", name = "Андуин Ринн", note = "мальчик-король, которого он защищает" },
		{ id = "varian-wrynn", name = "Вариан Ринн", note = "король, которому он служит" },
		{ id = "katrana-prestor", name = "Катрана Престор", note = "его самая доверенная советница" },
		{ id = "master-mathias-shaw", name = "мастер Матиас Шоу", note = "глава его разведки" },
		{ id = "major-samuelson", name = "майор Самуэльсон", note = "офицер его стражи" },
	},
})

Translate("ruRU", "katrana-prestor", {
	title = "Катрана Престор",
	subtitle = "Дама двора Штормграда",
	found = "Тронный зал Крепости Штормграда",
	hint = "Разыщите знатную даму, которая стоит рядом с регентом.",
	allegiance = "Королевство Штормград · Двор",
	aliases = { "Катрана", "леди Катрана Престор", "леди Престор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Леди Катрана Престор — знатная дама с большим влиянием. Она стоит в тронном зале Крепости {link:stormwind-city}Штормград{/link}а рядом с верховным лордом {link:bolvar-fordragon}Болвар{/link}ом Фордрагоном и говорит от имени двора, когда двору нужно говорить. Просители, приходящие в крепость, часто обнаруживают, что их слова доходят до регента лишь после того, как дошли до нее.]=],
		},
		{
			title = "Значение",
			text = [=[При дворе без короля совет доверенного советника имеет силу закона. Голос леди Престор звучит в каждом большом вопросе державы: чем королевство может поступиться, кому ему следует верить и какие из его бед можно без опаски оставить без внимания. Одни в королевстве восхищаются ее мудростью. Другие, вдали от столицы, начали задаваться вопросом, почему их мольбы так редко находят ответ.

Она присутствует всегда. Когда регент принимает прошение, она рядом с ним. Когда приходит донесение для отсутствующего короля, принимает его она. Когда регент должен решить, он прежде спрашивает ее совета. Ни один лорд палаты знати не занимает места столь близкого к сердцу королевства.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она дает регенту советы в делах королевства.
• Она принимает донесения на имя отсутствующего короля.
• Тем, кто спрашивает, она говорит, что король отбыл с дипломатическим поручением.]=],
		},
		{
			title = "Чего не сохранили летописи",
			text = [=[Ни одна запись двора не говорит, откуда явилась леди Престор и когда она впервые прибыла в {link:stormwind-keep}Крепость Штормграда{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Донесение для короля",
			hint = "Доставьте королю донесение о Братстве Справедливости.",
			text = [=[Донесение было на имя короля. В нем говорилось о Братстве Справедливости, об измене, которую совершил {link:gregor-lescovar}лорд Грегор Лесковар{/link}, и об убийце в королевском саду. Леди Престор приняла его сама. Она поблагодарила того, кто его принес, и объяснила, что король отбыл с дипломатическим поручением.]=],
		},
		{
			title = "Совет регенту",
			hint = "Доставьте мольбу Приозерья в Крепость Штормграда.",
			text = [=[Когда {link:lakeshire}Приозерье{/link} умоляло корону помочь {link:redridge-mountains}Красногорью{/link}, регент не желал отвечать, пока не выскажется леди Престор. Она выслушала мольбу и дала свой совет. Лишь тогда {link:bolvar-fordragon}Болвар{/link} написал свой указ.]=],
		},
		{
			title = "Большой маскарад",
			hint = "Увидьте двор Штормграда таким, каков он на самом деле.",
			text = [=[Когда маршал {red:reginald-windsor}Реджинальд Виндзор{/red} пришел в тронный зал со своими доказательствами, леди Престор осмеяла его и потребовала взять его под стражу. Затем она сбросила личину. Леди Катрана Престор никогда не была знатной дамой. То была {link:onyxia}Ониксия{/link}, дочь {link:deathwing}Смертокрыла{/link}, черный дракон, носивший человеческое лицо при дворе {link:stormwind-city}Штормград{/link}а. Все время, что она стояла рядом с регентом, род черных драконов владел слухом королевства. {link:wynd-nightchaser}Винд{/link}зор погиб в тронном зале. Ониксия бежала, и регенту осталось выяснять, как долго он был ее марионеткой.]=],
		},
	},
	mentions = {
		{ text = "Аудиенция у короля" },
		{ text = "Истинные хозяева" },
		{ text = "Большой маскарад" },
	},
	bonds = {
		{ id = "bolvar-fordragon", name = "Болвар Фордрагон", note = "регент, которому она дает советы" },
		{ id = "anduin-wrynn", name = "Андуин Ринн", note = "мальчик-король ее двора" },
		{ id = "varian-wrynn", name = "Вариан Ринн", note = "король, который, по ее словам, в отъезде" },
	},
})

Translate("ruRU", "archbishop-benedictus", {
	title = "Архиепископ Бенедикт",
