	},
	chapters = {
		{
			title = "Проклятое око",
			hint = [=[Принесите архиепископу реликвию, которая нуждается в очищении.]=],
			text = [=[Из Болотины привезли Око Палета — реликвию, искаженную проклятием. Ее не уничтожили там, где нашли. Ее отвезли в {link:stormwind-city}Штормград{/link} и вложили в руки архиепископа, ибо в королевстве мало тех, кто мог бы очистить такую вещь.]=],
		},
		{
			title = "Несущий холод",
			hint = [=[Откликнитесь на призыв архиепископа против лича из Курганов Иглошкурых.]=],
			text = [=[Далеко на юге, в {link:kalimdor}Калимдоре{/link}, в тернистых залах {link:quilboar}свинобразов{/link}, устроило себе дом порождение нежизни по имени {link:amnennar-the-coldbringer}Амненнар Хладовей{/link}. Бенедикт не ждет, пока такое зло пересечет море. Он просит защитников разыскать эту тварь и покончить с ней во имя {link:holy-light}Свет{/link}а.]=],
