})

Translate("ruRU", "baros-alexston", {
	title = "Барос Алекстон",
	subtitle = "Городской зодчий Штормграда",
	found = "Ратуша, Соборная площадь",
	hint = "Найдите городского зодчего в Ратуше, на Соборной площади.",
