			hint = "Верните старый компас зодчего из его дома в Западном Крае.",
			text = [=[Когда-то у него был дом в {link:westfall}Западном Крае{/link}. Он кое-что там оставил: старый компас, орудие своего первого ремесла. Западный Край теперь опасен, а его фермы достались ворам и разрухе. Но строитель не забывает инструмент, который первым научил его проводить прямую линию.]=],
		},
		{
			title = "Неотправленное письмо",
			hint = [=[Принесите зодчему письмо, найденное среди вещей, которые оставил ван Клиф.]=],
			text = [=[{link:edwin-vancleef}Эдвин ван Клиф{/link} написал письмо зодчему и запечатал его, но оно так и не покинуло {link:the-deadmines}Мертвые копи{/link}. Когда оно наконец попало в руки зодчего, тот внимательно его прочел. Его слова обратили мысли зодчего к Тюрьме, где держали одного из помощников главы Братства — узника Базиля {link:bazil-thredd}Тредд{/link}а.]=],
		},
		{
			title = "Письмо из Аубердина",
			hint = [=[Доставьте письмо старейшины Аубердина через море в Штормград.]=],
			text = [=[Старейшина {link:auberdine}Аубердина{/link}, {link:thundris-windweaver}Тандрис Ткач Ветров{/link}, написал зодчему с просьбой не забывать о его маленьком городе. Барос рассмеялся, когда пришел податель письма, и его улыбка угасала, пока он читал. Его ответ был честным. Казна {link:stormwind-city}Штормград{/link}а уже не та, что прежде, а то, что осталось, растянуто до предела. Ему нечего было послать, кроме своих сожалений.]=],
		},
	},
	mentions = {
		{ text = "Скромное начало" },
		{ text = "Неотправленное письмо" },
		{ text = "{link:bazil-thredd}Базиль Тредд{/link}" },
		{ text = "Любопытный посетитель" },
		{ text = "Тень прошлого" },
		{ text = "Конец Братства" },
		{ text = "Аудиенция у короля" },
		{ text = "Расширяя горизонты" },
		{ text = "Чем богаты" },
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Эдвин ван Клиф", note = "написал ему письмо, которое не было отправлено" },
		{ id = "warden-thelwater", name = "смотритель Телвотер", note = "хранит Тюрьму" },
		{ id = "master-mathias-shaw", name = "мастер Матиас Шоу", note = "глава SI:7" },
		{ id = "katrana-prestor", name = "Катрана Престор", note = "приняла его донесение для короля" },
	},
})

